function MoonPhase({ status, onClick }) {
  const cfg = {
    online: { fill: COLORS.gold, ring: COLORS.gold, label: "Online" },
    offline: { fill: "transparent", ring: COLORS.inkFaint, label: "Offline" },
    processing: { fill: COLORS.gold, ring: COLORS.gold, label: "In session" },
  }[status] || { fill: "transparent", ring: COLORS.inkFaint, label: status };

  return (
    <span
      onClick={onClick}
      title={onClick ? "Click to toggle status" : undefined}
      style={{ display: "inline-flex", alignItems: "center", gap: 6, cursor: onClick ? "pointer" : "default" }}
    >
      <span style={{
        width: 10, height: 10, borderRadius: "50%",
        border: `1.5px solid ${cfg.ring}`,
        background: status === "processing"
          ? `linear-gradient(90deg, ${cfg.fill} 50%, transparent 50%)`
          : cfg.fill,
      }} />
      <span style={{ fontSize: 12, color: COLORS.inkSoft, fontFamily: "Inter, sans-serif" }}>{cfg.label}</span>
    </span>
  );
}

function StatCard({ label, value, sub, icon: Icon, accent, accentSoft, spark, trendDown }) {
  const gradId = `spark-${label.replace(/\s+/g, "")}`;
  return (
    <div className="stat-card" style={{ "--accent": accent || COLORS.gold, "--accent-soft": accentSoft || COLORS.goldSoft }}>
      <div className="stat-card-glow" style={{ background: accent || COLORS.gold }} />
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", position: "relative", zIndex: 1 }}>
        <span style={{ fontFamily: "Inter, sans-serif", fontSize: 12.5, color: COLORS.inkSoft, letterSpacing: "0.02em" }}>{label}</span>
        <div className="stat-icon-chip">
          <Icon size={16} color={accent || COLORS.gold} />
        </div>
      </div>
      <div style={{ fontFamily: "IBM Plex Mono, monospace", fontSize: 28, fontWeight: 600, color: COLORS.ink, marginTop: 10, position: "relative", zIndex: 1 }}>{value}</div>
      <div style={{ display: "flex", alignItems: "flex-end", justifyContent: "space-between", marginTop: 6, position: "relative", zIndex: 1 }}>
        {sub ? (
          <div style={{ display: "flex", alignItems: "center", gap: 4, fontFamily: "Inter, sans-serif", fontSize: 12, color: COLORS.success }}>
            <TrendingUp size={12} style={trendDown ? { transform: "scaleY(-1)" } : undefined} />
            {sub}
          </div>
        ) : <span />}
        {spark && (
          <div style={{ width: 64, height: 28, marginBottom: -4 }}>
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={spark} margin={{ top: 2, bottom: 0, left: 0, right: 0 }}>
                <defs>
                  <linearGradient id={gradId} x1="0" y1="0" x2="0" y2="1">
                    <stop offset="0%" stopColor={accent || COLORS.gold} stopOpacity={0.5} />
                    <stop offset="100%" stopColor={accent || COLORS.gold} stopOpacity={0} />
                  </linearGradient>
                </defs>
                <Area type="monotone" dataKey="v" stroke={accent || COLORS.gold} strokeWidth={1.75} fill={`url(#${gradId})`} dot={false} isAnimationActive={false} />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        )}
      </div>
    </div>
  );
}

