    <span onClick={onClick} style={{ color: COLORS.ink, cursor: "pointer", fontWeight: 500 }}
      onMouseEnter={(e) => { e.currentTarget.style.color = COLORS.gold; e.currentTarget.style.textDecoration = "underline"; }}
      onMouseLeave={(e) => { e.currentTarget.style.color = COLORS.ink; e.currentTarget.style.textDecoration = "none"; }}
    >{children}</span>
