function UserSearchSelect({ clients, value, onChange, inputStyle }) {
  const [query, setQuery] = useState("");
  const [open, setOpen] = useState(false);
  const wrapRef = useRef(null);
  const selected = clients.find((c) => c.id === value);

  useEffect(() => {
    const onClickOutside = (e) => {
      if (wrapRef.current && !wrapRef.current.contains(e.target)) setOpen(false);
    };
    document.addEventListener("mousedown", onClickOutside);
    return () => document.removeEventListener("mousedown", onClickOutside);
  }, []);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return clients;
    return clients.filter((c) => c.name.toLowerCase().includes(q) || c.email?.toLowerCase().includes(q));
  }, [clients, query]);

  return (
    <div ref={wrapRef} style={{ position: "relative" }}>
      <div
        onClick={() => setOpen((o) => !o)}
        style={{ ...inputStyle, display: "flex", alignItems: "center", justifyContent: "space-between", marginTop: 4, width: "100%", cursor: "pointer", boxSizing: "border-box" }}
      >
        <span style={{ color: selected ? COLORS.ink : COLORS.inkFaint }}>{selected ? selected.name : "Select a user"}</span>
        <Search size={14} color={COLORS.inkFaint} />
      </div>
      {open && (
        <div style={{
          position: "absolute", top: "calc(100% + 4px)", left: 0, right: 0, zIndex: 30,
          background: COLORS.surfaceElevated, border: `1px solid ${COLORS.border}`, borderRadius: 8,
          boxShadow: "0 12px 30px rgba(0,0,0,0.4)", maxHeight: 220, overflow: "hidden", display: "flex", flexDirection: "column",
        }}>
          <div style={{ padding: 8, borderBottom: `1px solid ${COLORS.border}` }}>
            <input
              autoFocus
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Search by name or email..."
              style={{ ...inputStyle, width: "100%", boxSizing: "border-box" }}
            />
          </div>
          <div style={{ overflowY: "auto" }}>
            {filtered.length === 0 && (
              <div style={{ padding: "10px 12px", fontSize: 13, color: COLORS.inkFaint }}>No users found.</div>
            )}
            {filtered.map((c) => (
              <div
                key={c.id}
                onClick={() => { onChange(c.id); setQuery(""); setOpen(false); }}
                style={{
                  padding: "8px 12px", fontSize: 13, cursor: "pointer", color: COLORS.ink,
                  background: c.id === value ? COLORS.primarySoft : "transparent",
                  display: "flex", alignItems: "center", gap: 8,
                }}
                onMouseEnter={(e) => { if (c.id !== value) e.currentTarget.style.background = COLORS.surface; }}
                onMouseLeave={(e) => { if (c.id !== value) e.currentTarget.style.background = "transparent"; }}
              >
                <ProfileAvatar name={c.name} size={22} avatarColor={c.avatarColor} avatarUrl={c.avatarUrl} />
                <div>
                  <div>{c.name}</div>
                  <div style={{ fontSize: 11, color: COLORS.inkFaint }}>{c.email}</div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

function ProfileAvatar({ name, size = 56, avatarUrl, avatarColor }) {
  const [failed, setFailed] = useState(false);
  const initials = name.split(" ").map((w) => w[0]).slice(0, 2).join("").toUpperCase();
  const bg = avatarColor || COLORS.goldSoft;
  const fg = avatarColor ? "#ffffff" : COLORS.gold;

  if (avatarUrl && !failed) {
    return (
      <img
        src={avatarUrl} alt={name}
        onError={() => setFailed(true)}
        style={{ width: size, height: size, borderRadius: "50%", objectFit: "cover", flexShrink: 0, display: "block", background: bg }}
      />
    );
  }
  return (
    <svg width={size} height={size} viewBox="0 0 100 100" style={{ borderRadius: "50%", flexShrink: 0, display: "block" }}>
      <circle cx="50" cy="50" r="50" fill={bg} />
      <text x="50" y="64" textAnchor="middle" fontFamily="Georgia, 'Times New Roman', serif" fontWeight="600" fontSize="38" fill={fg}>{initials}</text>
    </svg>
  );
}

function StatBlock({ label, value }) {
  return (
    <div>
      <div style={{ fontSize: 11, color: COLORS.inkFaint, textTransform: "uppercase", letterSpacing: "0.04em" }}>{label}</div>
      <div style={{ fontFamily: "IBM Plex Mono, monospace", fontSize: 16, fontWeight: 600, color: COLORS.ink, marginTop: 2 }}>{value}</div>
    </div>
  );
}


function FileIcon({ kind }) {
  const cfg = { image: ImageIcon, video: Film, pdf: FileText }[kind] || FileText;
  const Icon = cfg;
  return <Icon size={13} color={COLORS.inkSoft} />;
}

function Thumb({ url, name, kind, emoji, color, ratio, width }) {
  const sizeStyle = ratio ? { width: width || 80, aspectRatio: ratio, height: "auto" } : {};
  if (url) {
    return (
      <div className="thumb-box" style={{ background: COLORS.surfaceElevated, border: `1px solid ${COLORS.border}`, ...sizeStyle }}>
        <img src={url} alt={name} className="thumb-img" style={{ objectFit: "cover" }} />
        {kind === "video" && (
          <div className="thumb-play"><Film size={13} color="#fff" /></div>
        )}
      </div>
    );
  }
  if (emoji) {
    return (
      <div className="thumb-box" style={{ background: color || COLORS.surfaceElevated, border: `1px solid ${COLORS.border}`, position: "relative", ...sizeStyle }}>
        <svg width="100%" height="100%" viewBox="0 0 60 60" style={{ display: "block" }}>
          <rect width="60" height="60" rx="10" fill={color || COLORS.surfaceElevated} />
          <text x="30" y="40" textAnchor="middle" fontSize="30">{emoji}</text>
        </svg>
        {kind === "video" && (
          <div className="thumb-play"><Film size={13} color="#fff" /></div>
        )}
      </div>
    );
  }
  return (
    <div className="thumb-box" style={{
      background: COLORS.surfaceElevated, border: `1px solid ${COLORS.border}`,
      display: "flex", alignItems: "center", justifyContent: "center",
      fontFamily: "Fraunces, serif", fontWeight: 600, color: COLORS.gold, ...sizeStyle,
    }}>{name ? name[0].toUpperCase() : "?"}</div>
  );
}

